        for tag, text in (("tabs", "k\tp\n0\t1\n\t\n1\t2\n"), ("spaces", "k\tp\n0\t1\n   \n1\t2\n"),
                          ("empty line", "k\tp\n0\t1\n\n1\t2\n")):
            with self.assertRaises(ns["TsvShapeError"], msg=tag) as cm:
                ns["_read_tsv"](self._w("ws.tsv", text))
