class TestQ887Gate22UniverseRc(unittest.TestCase):
    """Lane D31: Q-887's minor sibling. GATE 22's 64-nibble UNIVERSE grep (`git grep -ohIE '[0-9a-f]+'
    HEAD ...`) ran `2>/dev/null` with no rc check. In a clean tree that failed closed through the
    empty-universe [FAIL], but nothing named the producer, and in a dirty tree the working-tree leg
    could refill the universe and hide it. The rc is now captured and rc >= 2 is a FAIL naming the
    universe producer. A PATH git shim refuses ONLY that grep (keyed on the pattern AND `HEAD`)."""

    ROOT = os.path.dirname(os.path.abspath(__file__))

    def test_universe_producer_failure_is_named(self):
        tmp = tempfile.mkdtemp(prefix="q887_g22_")
        try:
            real = shutil.which("git")
            acted = os.path.join(tmp, "acted")
            with open(os.path.join(tmp, "git"), "w", encoding="utf-8") as fh:
                fh.write("#!/usr/bin/env bash\nhp=0; hh=0\nfor a in \"$@\"; do [ \"$a\" = '[0-9a-f]+' ] && hp=1; "
                         "[ \"$a\" = HEAD ] && hh=1; done\nif [ $hp = 1 ] && [ $hh = 1 ]; then touch '%s'; "
                         "echo 'q887 shim: git grep refused' >&2; exit 2; fi\nexec '%s' \"$@\"\n" % (acted, real))
            os.chmod(os.path.join(tmp, "git"), 0o755)
            env = dict(os.environ, PATH=tmp + os.pathsep + os.environ["PATH"])
            r = subprocess.run(["bash", "scripts/doc_gates.sh", "hex-prefix"], capture_output=True, text=True,
                               env=env, cwd=self.ROOT, timeout=900)
            self.assertTrue(os.path.exists(acted), "precondition: the PATH git shim was never reached")
            out = r.stdout + r.stderr
            self.assertNotEqual(r.returncode, 0)
            self.assertTrue("GATE 22: the universe producer (git grep over HEAD) failed rc 2" in out,
                            "the universe producer's failure was not named:\n" + out[:1500])
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

# end class TestQ887Gate22UniverseRc (lane D31)



class TestQ884TR12GoldenSet(unittest.TestCase):
    """Lane D31: Q-884 GAP-2. scripts/tr12_golden_set_gate.sh reconciles scripts/tr12_expected/n9/*.txt
    with the battery's own row list (and with _MANIFEST.txt): an orphan golden, a golden missing from
    disk or from the manifest, or a row with no golden that is not pinned NOT RUN, is FAIL. Each case
    runs against a scratch copy (TR12_GOLDEN_ROOT) and first asserts the clean copy PASSES with at
    least the known row count, so a red can only come from the planted change."""

    ROOT = os.path.dirname(os.path.abspath(__file__))
    GATE = os.path.join("scripts", "tr12_golden_set_gate.sh")
    KNOWN_ROWS = 77
    KNOWN_GOLDENS = 60

    def setUp(self):
        self.tmp = tempfile.mkdtemp(prefix="q884_gs_")
        os.makedirs(os.path.join(self.tmp, "scripts", "tr12_expected"))
        shutil.copy(os.path.join(self.ROOT, "scripts", "tr12_repro.sh"), os.path.join(self.tmp, "scripts"))
        shutil.copytree(os.path.join(self.ROOT, "scripts", "tr12_expected", "n9"),
                        os.path.join(self.tmp, "scripts", "tr12_expected", "n9"))
        self.n9 = os.path.join(self.tmp, "scripts", "tr12_expected", "n9")

    def tearDown(self):
        shutil.rmtree(self.tmp, ignore_errors=True)

    def _run(self, root):
        self.assertTrue(os.path.isfile(os.path.join(self.ROOT, self.GATE)), "the golden-set gate is missing")
        env = dict(os.environ, TR12_GOLDEN_ROOT=root)
        r = subprocess.run(["bash", os.path.join(self.ROOT, self.GATE)], capture_output=True, text=True,
                           env=env, timeout=300)
        lines = r.stdout.splitlines()
        v = [l for l in lines if l.startswith("TR12_GOLDEN_SET=")]
        self.assertEqual(len(v), 1, r.stdout + r.stderr)
        return r.returncode, v[0], r.stdout

    def _rows(self, out):
        m = re.search(r"^TR12_GOLDEN_ROWS=(\d+)$", out, re.M)
        self.assertIsNotNone(m, out)
        return int(m.group(1))

    def test_real_tree_passes_at_known_counts(self):
        rc, v, out = self._run(self.ROOT)
        self.assertEqual((rc, v), (0, "TR12_GOLDEN_SET=PASS"), out)
        self.assertGreaterEqual(self._rows(out), self.KNOWN_ROWS)
        self.assertIn("TR12_GOLDENS=%d" % self.KNOWN_GOLDENS, out.splitlines())

    def test_clean_copy_passes(self):
        rc, v, out = self._run(self.tmp)
        self.assertEqual((rc, v), (0, "TR12_GOLDEN_SET=PASS"), out)
        self.assertGreaterEqual(self._rows(out), self.KNOWN_ROWS, "precondition: the row list parsed")

    def test_orphan_golden_is_fail(self):
        shutil.copy(os.path.join(self.n9, "a0_anchor.txt"), os.path.join(self.n9, "zz_orphan.txt"))
        rc, v, out = self._run(self.tmp)
        self.assertEqual((rc, v), (1, "TR12_GOLDEN_SET=FAIL"), out)
        self.assertIn("orphan: golden zz_orphan.txt names no row", out)

    def test_deleted_golden_is_fail(self):
        os.remove(os.path.join(self.n9, "a0_anchor.txt"))
        rc, v, out = self._run(self.tmp)
        self.assertEqual((rc, v), (1, "TR12_GOLDEN_SET=FAIL"), out)
        self.assertIn("manifest-missing: _MANIFEST.txt lists a0_anchor.txt", out)
        self.assertIn("row-no-golden: row a0_anchor has no golden", out)

    def test_deleted_golden_and_manifest_line_is_still_fail(self):
        os.remove(os.path.join(self.n9, "a0_anchor.txt"))
        mp = os.path.join(self.n9, "_MANIFEST.txt")
        with open(mp, encoding="utf-8") as fh:
            kept = [l for l in fh if not l.rstrip().endswith(" a0_anchor.txt")]
        with open(mp, "w", encoding="utf-8") as fh:
            fh.writelines(kept)
        rc, v, out = self._run(self.tmp)
        self.assertEqual((rc, v), (1, "TR12_GOLDEN_SET=FAIL"), out)
        self.assertNotIn("manifest-missing", out)
        self.assertIn("row-no-golden: row a0_anchor has no golden", out)

    def test_wired_into_the_reproduction_gate_before_the_stamp(self):
        with open(os.path.join(self.ROOT, "scripts", "tr12_repro_gate.sh"), encoding="utf-8") as fh:
            src = fh.read()
        a = src.find("bash ./scripts/tr12_golden_set_gate.sh")
        b = src.find("FP=$(fingerprint)\n    {")
        self.assertGreater(a, 0, "the golden-set leg is not called by tr12_repro_gate.sh")
        self.assertGreater(b, a, "the golden-set leg must run before the stamp is written")

# end class TestQ884TR12GoldenSet (lane D31)


class TestQ884RetractDerived(unittest.TestCase):
    """Lane D31: Q-884 GAP-1. doc_gates GATE 94 (`retract-derived`, ADVISORY) derives withdrawn-phrase
    candidates from CORRECTIONS.md quotes and reports those RETRACTED_PHRASES.tsv does not register.
    It never fails the run. Fixtures replace the ledger, the registry and the live corpus."""

    ROOT = os.path.dirname(os.path.abspath(__file__))
    PHRASE = "the q884 fixture claim holds everywhere"

    def _run(self, corr, reg):
        tmp = tempfile.mkdtemp(prefix="q884_rd_")
        try:
            cp, rp = os.path.join(tmp, "CORR.md"), os.path.join(tmp, "REG.tsv")
            with open(cp, "w", encoding="utf-8") as fh:
                fh.write(corr)
            with open(rp, "w", encoding="utf-8") as fh:
                fh.write(reg)
            os.makedirs(os.path.join(tmp, "corpus"))
            env = dict(os.environ, DOC_GATE_RD_CORR=cp, DOC_GATE_RD_REG=rp,
                       DOC_GATE_RD_CORPUS=os.path.join(tmp, "corpus"))
            r = subprocess.run(["bash", "scripts/doc_gates.sh", "retract-derived"], capture_output=True,
                               text=True, env=env, cwd=self.ROOT, timeout=300)
            return r.returncode, r.stdout
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_unregistered_quote_is_advisory_n1_and_exit_0(self):
        rc, out = self._run('## CX-1 — fixture\nThe summary read "%s" and is withdrawn.\n' % self.PHRASE,
                            "# registry\nsome other phrase entirely\tCORRECTIONS.md\tnote\n")
        self.assertIn("RETRACT_DERIVED_CANDIDATES=1", out.splitlines(), "precondition: one quote extracted")
        self.assertIn("RETRACT_DERIVED=ADVISORY n=1", out.splitlines(), out[-1500:])
        self.assertEqual(rc, 0, "an advisory leg must never fail the run")

    def test_registered_quote_is_pass_n0(self):
        rc, out = self._run('## CX-1 — fixture\nThe summary read "%s" and is withdrawn.\n' % self.PHRASE,
                            "# registry\n%s\tCORRECTIONS.md\tnote\n" % self.PHRASE)
        self.assertIn("RETRACT_DERIVED_CANDIDATES=1", out.splitlines(), "precondition: one quote extracted")
        self.assertIn("RETRACT_DERIVED=PASS", out.splitlines(), out[-1500:])
        self.assertEqual(rc, 0)

    def test_real_ledger_population_at_or_above_floor(self):
        r = subprocess.run(["bash", "scripts/doc_gates.sh", "retract-derived"], capture_output=True,
                           text=True, cwd=self.ROOT, timeout=300)
        self.assertEqual(r.returncode, 0)
        m = re.search(r"^RETRACT_DERIVED_CANDIDATES=(\d+)$", r.stdout, re.M)
        self.assertIsNotNone(m, r.stdout[-1500:])
        self.assertGreaterEqual(int(m.group(1)), 40)
        self.assertTrue(re.search(r"^RETRACT_DERIVED=(PASS|ADVISORY n=\d+)$", r.stdout, re.M), r.stdout[-1500:])

# end class TestQ884RetractDerived (lane D31)



class TestQ572CitationContentRule(unittest.TestCase):
    """Q-572. citation_line_gate.sh --all-files accepted a landing for .c/.py/.md targets whenever a
    mined identifier appeared anywhere in the cited span (+-2), so a citation of "the read loop bounded
    by n_records" that sat on a printf merely passing n_records reported clean. Lane D31 (batch 31)
    added the CONTENT RULE as an advisory count; batch 32 repaired the wrong citations it found and made
    it BLOCKING: an unreviewed content-weak landing, or a reviewed CONTENT_PINS row that no longer
    matches one, is a VERDICT FAIL, and CITATION_CONTENT_RULE=PASS|FAIL is printed beside
    CITATION_LINE_GATE. Fixtures are throwaway git repos read through CITGATE_ROOT. RED: the advisory
    mutant (batch 31's semantics: the rule counts but never fails) and a rule-less mutant both PASS the
    planted off-by-two citation that the live gate FAILs."""

    ROOT = os.path.dirname(os.path.abspath(__file__))
    GATE = os.path.join("scripts", "citation_line_gate.sh")
    SRC = ("int a;\n"                                                   # 1
           "long long n_records = count();\n"                           # 2
           "printf(\"[verify] records=%lld\\n\", n_records);\n"         # 3
           "long long done = 0;\n"                                      # 4
           "/* n_records is the header count */\n"                      # 5
           "while (done < n_records) {\n"                               # 6
           "    done += step(n_records);\n"                             # 7
           "}\n")                                                       # 8

    def _repo(self, line_no):
        d = tempfile.mkdtemp(prefix="q572_")
        self.addCleanup(shutil.rmtree, d, True)
        with open(os.path.join(d, "solve.c"), "w", encoding="utf-8") as fh:
            fh.write(self.SRC)
        with open(os.path.join(d, "doc.md"), "w", encoding="utf-8") as fh:
            fh.write("The read loop is bounded by it (`n_records`, solve.c:%d).\n" % line_no)
        g = ["git", "-C", d, "-c", "user.name=t", "-c", "user.email=t@invalid"]
        for cmd in (["init", "-q"], ["add", "-A"], ["commit", "-q", "-m", "base"]):
            r = subprocess.run(g + cmd, capture_output=True, text=True)
            self.assertEqual(r.returncode, 0, r.stderr)
        return d

    def _pin(self, line_no):
        """A CONTENT_PINS row for doc.md -> solve.c at line_no, hashed the way the gate's chash() does."""
        body = self.SRC.split("\n")[line_no - 1].rstrip()
        return "doc.md\tsolve.c\t%s\treviewed fixture pin" % hashlib.sha256(body.encode()).hexdigest()[:12]

    def _run(self, root, gate=None, cpins="", extra=()):
        env = dict(os.environ, CITGATE_ROOT=root, CITGATE_ALL_PINS="", CITGATE_TARGET_PINS="",
                   CITGATE_CONTENT_PINS=cpins)
        r = subprocess.run(["bash", gate or os.path.join(self.ROOT, self.GATE), "--all-files", *extra],
                           capture_output=True, text=True, env=env, cwd=self.ROOT, timeout=300)
        lines = r.stdout.splitlines()
        v = [l for l in lines if l.startswith("CITATION_LINE_GATE=")]
        c = [l for l in lines if l.startswith("CITATION_CONTENT_RULE=")]
        self.assertEqual(len(v), 1, r.stdout[-2000:])
        return v[0], c, r.stdout

    def _mutant(self, live, repl):
        with open(os.path.join(self.ROOT, self.GATE), encoding="utf-8") as fh:
            src = fh.read()
        self.assertEqual(src.count(live), 1, "precondition: the mutated text is present once")
        d = tempfile.mkdtemp(prefix="q572m_")
        self.addCleanup(shutil.rmtree, d, True)
        os.makedirs(os.path.join(d, "scripts"))
        mp = os.path.join(d, "scripts", "citation_line_gate.sh")
        with open(mp, "w", encoding="utf-8") as fh:
            fh.write(src.replace(live, repl))
        return mp

    def test_precondition_fixture_shape(self):
        src = self.SRC.split("\n")
        self.assertIn("printf", src[2])
        self.assertIn("while (done < n_records)", src[5])
        self.assertGreater(sum("n_records" in l for l in src), 3, "n_records must be COMMON (> RARE lines)")
        self.assertNotIn("n_records", src[3], "line 4, the planted citation, must not carry the anchor")

    def test_correct_citation_passes(self):
        v, c, out = self._run(self._repo(6))
        self.assertEqual(v, "CITATION_LINE_GATE=PASS", out[-1500:])
        self.assertEqual(c, ["CITATION_CONTENT_RULE=PASS"], out[-1500:])

    def test_planted_off_by_two_fails(self):
        v, c, out = self._run(self._repo(4))
        self.assertEqual(v, "CITATION_LINE_GATE=FAIL", out[-1500:])
        self.assertEqual(c, ["CITATION_CONTENT_RULE=FAIL"], out[-1500:])
        self.assertIn("[NEW-weak] doc.md:1 solve.c:4", out)

    def test_print_argument_landing_fails(self):
        v, c, out = self._run(self._repo(3))
        self.assertEqual(v, "CITATION_LINE_GATE=FAIL", out[-1500:])
        self.assertEqual(c, ["CITATION_CONTENT_RULE=FAIL"], out[-1500:])

    def test_reviewed_pin_passes_and_is_exact(self):
        v, c, out = self._run(self._repo(4), cpins=self._pin(4))
        self.assertEqual((v, c), ("CITATION_LINE_GATE=PASS", ["CITATION_CONTENT_RULE=PASS"]), out[-1500:])
        v, c, out = self._run(self._repo(6), cpins=self._pin(4))      # the citation was repaired
        self.assertEqual((v, c), ("CITATION_LINE_GATE=FAIL", ["CITATION_CONTENT_RULE=FAIL"]), out[-1500:])
        self.assertIn("[weak-pin-unmatched] doc.md -> solve.c #", out)
        v, c, out = self._run(self._repo(4), cpins=self._pin(5))      # a pin for other content
        self.assertEqual(v, "CITATION_LINE_GATE=FAIL", out[-1500:])

    def test_advisory_mutant_is_red(self):
        mp = self._mutant("if wnew:\n    bad.append(", "if False:\n    bad.append(")
        v, c, out = self._run(self._repo(4), gate=mp)
        self.assertEqual(v, "CITATION_LINE_GATE=PASS", "the advisory mutant must pass the off-by-two")

    def test_ruleless_mutant_is_red(self):
        mp = self._mutant("if occ(tg, c) <= RARE or any(c in l and not print_arg_only(tg, c, l) for l in core):",
                          "if True:")
        v, c, out = self._run(self._repo(4), gate=mp)
        self.assertEqual((v, c), ("CITATION_LINE_GATE=PASS", ["CITATION_CONTENT_RULE=PASS"]),
                         "the rule-less mutant must miss the off-by-two")

    def test_real_tree_content_pins_are_reviewed_and_exact(self):
        with open(os.path.join(self.ROOT, self.GATE), encoding="utf-8") as fh:
            src = fh.read()
        m = re.search(r"CONTENT_PINS_DEFAULT=\$\(cat <<'PINS'\n(.*?)\nPINS\n", src, re.S)
        self.assertIsNotNone(m)
        rows = [r for r in m.group(1).split("\n") if r.strip() and not r.startswith("#")]
        self.assertGreaterEqual(len(rows), 1)
        for r in rows:
            f = r.split("\t")
            self.assertEqual(len(f), 4, r)
            self.assertRegex(f[2], r"^[0-9a-f]{12}$")
            self.assertTrue(f[3].startswith("CORRECT: "), "each pin states its review: %r" % r)
        r = subprocess.run(["bash", self.GATE, "--all-files", "--all-targets"], capture_output=True,
                           text=True, cwd=self.ROOT, timeout=600)
        self.assertIn("\nCITATION_CONTENT_RULE=PASS\n", "\n" + r.stdout, r.stdout[-3000:])
        self.assertIn("reviewed-pins=%d new=0 pins-unmatched=0" % len(rows), r.stdout)

# end class TestQ572CitationContentRule (lane D31; blocking, batch 32)



@unittest.skipUnless(shutil.which("setsid") and shutil.which("git"), "needs setsid and git")
class TestQ435ExecLaneChainCarry(unittest.TestCase):
    """Lane D31: Q-435, the chain-carry half. scripts/exec_lane.sh ran every fenced command alone, keyed
    by its text, so a consumer of an earlier step's output was graded on its own (SKIP-MISSING-INPUT)
    and a consumer of a /tmp file read whatever a previous run had left there (reports/evidence/f5's
    stale-file PASS). It now runs a dependent block as ONE cwd chain (CHAINBREAK-AFTER-<n> when a step
    needs step n's output and does not get it) and redirects every /tmp/ path into the workspace.
    Each case runs the REAL lane via --tree on a fixture tree with a private TMPDIR. RED: a mutant with
    the chain phase switched off and the quarantine removed (BASE's behaviour) is run on the same
    fixtures and must give the old, wrong answers -- so every case here can fail."""

    LANE = os.path.abspath("scripts/exec_lane.sh")

    @classmethod
    def setUpClass(cls):
        cls.tmp = tempfile.mkdtemp(prefix="q435_")
        with open(cls.LANE, encoding="utf-8") as fh:
            src = fh.read()
        gate = 'if [ -s "$CHAINS" ] && [ -z "$ONLY" ]; then'
        quar = 'execmd="$(sed -E "s#(^|[[:space:]\\"\'=>(:])/tmp/#\\1$WS/.lane_tmp/#g" <<<"$execmd")"'
        cls.mutant_ok = src.count(gate) == 1 and src.count(quar) == 1
        cls.mutant = os.path.join(cls.tmp, "exec_lane_mutant.sh")
        with open(cls.mutant, "w", encoding="utf-8") as fh:
            fh.write(src.replace(gate, "if false; then").replace(quar, ":"))

    @classmethod
    def tearDownClass(cls):
        shutil.rmtree(cls.tmp, ignore_errors=True)

    def _tree(self, name, readme, extra=None):
        tree = os.path.join(self.tmp, name, "tree")
        os.makedirs(os.path.join(tree, "reports"))
        with open(os.path.join(tree, "README.md"), "w", encoding="utf-8") as fh:
            fh.write(readme)
        with open(os.path.join(tree, "reports", "TR1_X.md"), "w", encoding="utf-8") as fh:
            fh.write("# TR1\n\nEvery MEASURED result carries a reproduction command.\n")
        for rel, body in (extra or {}).items():
            with open(os.path.join(tree, rel), "w", encoding="utf-8") as fh:
                fh.write(body)
        env = dict(os.environ, GIT_AUTHOR_NAME="t", GIT_AUTHOR_EMAIL="t@example.invalid",
                   GIT_COMMITTER_NAME="t", GIT_COMMITTER_EMAIL="t@example.invalid")
        for a in (["init", "-q"], ["add", "-A"], ["commit", "-qm", "fixture"]):
            subprocess.run(["git", "-C", tree] + a, check=True, env=env, capture_output=True)
        return tree

    def _lane(self, tree, lane=None):
        tmpd = tempfile.mkdtemp(dir=self.tmp)
        env = dict(os.environ, TMPDIR=tmpd, EXEC_LANE_BUDGET="60")
        r = subprocess.run(["bash", lane or self.LANE, "--tree", tree], env=env, text=True,
                           capture_output=True, timeout=600)
        out = r.stdout
        self.assertIn(out.strip().splitlines()[-1], ("EXEC_LANE=PASS", "EXEC_LANE=FAIL"), out[-3000:])
        return out

    def test_proof_tokens_present(self):
        with open(self.LANE, encoding="utf-8") as fh:
            src = fh.read()
        self.assertIn("CHAINBREAK-AFTER-", src)
        self.assertIn("FAIL-UNBOUNDED", src)
        self.assertTrue(self.mutant_ok, "precondition: the BASE-behaviour mutant could be built")

    def test_consumer_of_a_file_its_producer_never_wrote_is_chainbreak_after_1(self):
        tree = self._tree("broken", "# f\n\n```\necho hello --out out.txt\ncat out.txt\n```\n")
        out = self._lane(tree)
        self.assertIn("CHAINBREAK-AFTER-1(step 1 PASSED but never produced out.txt)", out)
        self.assertEqual(out.strip().splitlines()[-1], "EXEC_LANE=FAIL", out[-3000:])
        base = self._lane(tree, self.mutant)
        self.assertIsNone(re.search(r"CHAINBREAK-AFTER-\d", base), "RED: BASE has no chain class")
        self.assertEqual(base.strip().splitlines()[-1], "EXEC_LANE=PASS", "RED: BASE passes the broken chain")

    def test_stale_tmp_file_cannot_satisfy_a_consumer(self):
        uniq = "/tmp/q435_stale_%d_%d.out" % (os.getpid(), random.randrange(10 ** 9))
        tree = self._tree("stale", "# f\n\n```\npython3 gen.py --rows ROWS > %s\ndiff expected.out %s\n```\n"
                          % (uniq, uniq), {"expected.out": "golden\n", "gen.py": 'print("golden")\n'})
        try:
            with open(uniq, "w", encoding="utf-8") as fh:
                fh.write("golden\n")
            with open(uniq, encoding="utf-8") as a, open(os.path.join(tree, "expected.out"), encoding="utf-8") as b:
                self.assertEqual(a.read(), b.read(), "precondition: the pre-seeded stale file matches the golden")
            out = self._lane(tree)
            diff = [l for l in out.splitlines() if l.rstrip().endswith("diff expected.out %s" % uniq)
                    and re.match(r"^\s*c?\d+\.", l)]
            self.assertTrue(diff, "precondition: the consumer was executed:\n" + out[-3000:])
            self.assertFalse(any(re.search(r"\bPASS\b", l) for l in diff), "the stale /tmp file satisfied the consumer:\n" + "\n".join(diff))
            base = self._lane(tree, self.mutant)
            bdiff = [l for l in base.splitlines() if l.rstrip().endswith("diff expected.out %s" % uniq)
                     and re.match(r"^\s*\d+\.", l)]
            self.assertTrue(bdiff and "PASS" in bdiff[0], "RED: BASE passed on the stale file:\n" + base[-2000:])
            with open(uniq, encoding="utf-8") as fh:
                self.assertEqual(fh.read(), "golden\n", "the lane must never touch the real /tmp file")
        finally:
            if os.path.exists(uniq):
                os.remove(uniq)

    def test_valid_chain_passes(self):
        tree = self._tree("valid", "# f\n\n```\necho hello > good.txt\ncat good.txt\n```\n")
        out = self._lane(tree)
        self.assertEqual(out.strip().splitlines()[-1], "EXEC_LANE=PASS", out[-3000:])
        self.assertIn("EXEC_LANE_CHAINS=1", out.splitlines())
        self.assertIn("EXEC_LANE_CHAIN_PASS=2", out.splitlines())
        self.assertIsNone(re.search(r"CHAINBREAK-AFTER-\d", out), out[-2000:])

    def test_reference_block_is_denied_the_chain(self):
        tree = self._tree("ref", "# f\n\n## Usage\n\n```\necho hello --out out.txt\ncat out.txt\n```\n")
        out = self._lane(tree)
        self.assertIn("EXEC_LANE_CHAINS=0", out.splitlines(), "a first fence under a Usage heading is a reference block")
        self.assertEqual(out.strip().splitlines()[-1], "EXEC_LANE=PASS", out[-3000:])

    def test_real_corpus_lists_the_f5_chain(self):
        r = subprocess.run(["bash", self.LANE, "--list"], capture_output=True, text=True, timeout=600)
        self.assertEqual(r.returncode, 0, r.stdout[-2000:])
        rows = [l for l in r.stdout.splitlines() if l.startswith("reports/evidence/f5/README.md:")]
        self.assertTrue(any("deps=" in l and "/tmp/f5_modec_fiber_rerun.out" in l and "diff " in l for l in rows),
                        "the f5 consumer must be listed with its /tmp dependency:\n" + "\n".join(rows))
        m = re.search(r"^EXEC_LANE_CHAINS=(\d+)$", r.stdout, re.M)
        self.assertIsNotNone(m)
        self.assertGreaterEqual(int(m.group(1)), 2)

# end class TestQ435ExecLaneChainCarry (lane D31)

# ---- lane G31 (2026-10-01): Q-410 SAT/CNF CLI edges from the Codex LSD review, row R22 ----------
class TestG31SatCliEdges(unittest.TestCase):
    """Four CLI edges, each a refusal with a named message and a non-zero exit now, each measured
    RED against BASE's file (public main 38feb643, loaded by `git show`) and GREEN on this tree.
    Every probe asserts that its input really is the edge case before grading the verdict."""
    ROOT = os.path.dirname(os.path.abspath(__file__))
    BASE = "38feb643"

    def _base_file(self, tmp, name):
        r = subprocess.run(["git", "-C", self.ROOT, "show", self.BASE + ":" + name],
                           capture_output=True, text=True)
        if r.returncode != 0 or not r.stdout:
            self.fail("git show %s:%s failed, so the red arm measured nothing: %s"
                      % (self.BASE, name, r.stderr[-400:]))
        p = os.path.join(tmp, "base_" + name)
        with open(p, "w", encoding="utf-8") as fh:
            fh.write(r.stdout)
        return p

    def _env(self, extra_path=None):
        env = dict(os.environ, PYTHONPATH=self.ROOT)   # BASE's sat.py must still `import solve`
        if extra_path:
            env["PATH"] = extra_path + os.pathsep + env.get("PATH", "")
        return env

    def _run(self, script, args, env=None, cwd=None):
        return subprocess.run([sys.executable, script] + args, capture_output=True, text=True,
                              env=env or self._env(), cwd=cwd or self.ROOT, timeout=600)

    # E1 -- a recognised modifier with no subcommand exited 0 after printing the catalogue
    def test_e1_modifier_without_subcommand_is_refused(self):
        # precondition: `--with-c3` IS a recognised modifier (it is consumed, so only the decoy
        # is reported as unrecognised); an unrecognised flag alone is a different refusal
        r = self._run("sat.py", ["--with-c3", "--no-such-flag-g31"])
        self.assertNotEqual(r.returncode, 0)
        self.assertIn("unrecognised flag(s): --no-such-flag-g31", r.stderr)
        self.assertNotIn("--with-c3", r.stderr.split("unrecognised flag(s):")[1].splitlines()[0])
        for args in (["--with-c3"], ["--expect", "26113"], ["--c3-max", "800"]):
            r = self._run("sat.py", args)
            self.assertNotEqual(r.returncode, 0, args)
            self.assertIn("given without a subcommand: nothing was run", r.stderr, args)
            self.assertNotIn("--emit-cnf TARGET", r.stdout, "the catalogue was printed")
        r = self._run("sat.py", [])                         # the documented no-argument form
        self.assertEqual(r.returncode, 0, r.stderr[-300:])
        self.assertIn("--emit-cnf", r.stdout)

    def test_e1_red_base_printed_the_catalogue_and_exited_0(self):
        with tempfile.TemporaryDirectory() as tmp:
            old = self._base_file(tmp, "sat.py")
            for args in (["--with-c3"], ["--expect", "26113"], ["--c3-max", "800"]):
                r = self._run(old, args)
                self.assertEqual(r.returncode, 0, (args, r.stderr[-300:]))
                self.assertIn("--emit-cnf", r.stdout, args)   # the catalogue, not a refusal

    # E2 -- a `v` line with a non-integer token was an uncaught ValueError traceback
    @staticmethod
    def _stub_kissat(tmp):
        d = os.path.join(tmp, "bin"); os.makedirs(d, exist_ok=True)
        p = os.path.join(d, "kissat")
        with open(p, "w") as fh:
            fh.write('#!/bin/sh\nprintf "s SATISFIABLE\\nv nope 0\\n"\nexit 10\n')
        os.chmod(p, 0o755)
        return d, p

    def test_e2_non_integer_v_token_is_solver_error_exit_2(self):
        with tempfile.TemporaryDirectory() as tmp:
            d, p = self._stub_kissat(tmp)
            env = self._env(d)
            self.assertEqual(shutil.which("kissat", path=env["PATH"]), p,
                             "the stub is not the kissat that will run; the probe is not the edge")
            r = self._run("sat.py", ["--witness", "plain"], env=env)
            self.assertEqual(r.returncode, 2, r.stdout[-400:] + r.stderr[-400:])
            lines = r.stdout.splitlines()
            self.assertIn("WITNESS_RESULT=SOLVER_ERROR", lines)
            self.assertTrue(any("non-integer token" in ln for ln in lines), r.stdout[-400:])
            self.assertNotIn("Traceback", r.stderr)

    def test_e2_red_base_raised_valueerror_with_no_token(self):
        with tempfile.TemporaryDirectory() as tmp:
            d, p = self._stub_kissat(tmp)
            env = self._env(d)
            self.assertEqual(shutil.which("kissat", path=env["PATH"]), p)
            old = self._base_file(tmp, "sat.py")
            r = self._run(old, ["--witness", "plain"], env=env)
            self.assertEqual(r.returncode, 1, r.stdout[-400:] + r.stderr[-400:])
            self.assertIn("ValueError: invalid literal for int()", r.stderr)
            self.assertFalse(any(ln.startswith("WITNESS_RESULT=") for ln in r.stdout.splitlines()),
                             "BASE printed a token; this is not the pre-fix parser")

    # E3 -- a stale OPB companion beside a run that writes none, with the sidecar saying null
    def test_e3_stale_opb_companion_is_refused_before_writing(self):
        with tempfile.TemporaryDirectory() as tmp:
            stale = os.path.join(tmp, "P.cnf.opb")
            with open(stale, "w") as fh:
                fh.write("* stale OPB from an earlier run\n")
            before = hashlib.sha256(open(stale, "rb").read()).hexdigest()
            r = self._run("solve.py", ["--sat-encode", os.path.join(tmp, "P.cnf"), "--sat-c3", "none"])
            self.assertEqual(r.returncode, 2, r.stdout[-400:] + r.stderr[-400:])
            self.assertIn("REFUSING: a stale OPB companion", r.stdout)
            self.assertFalse(os.path.exists(os.path.join(tmp, "P.cnf")), "the CNF was written anyway")
            self.assertFalse(os.path.exists(os.path.join(tmp, "P.cnf.meta.json")))
            self.assertEqual(hashlib.sha256(open(stale, "rb").read()).hexdigest(), before)
            # the pb form rewrites the companion and is not refused
            r = self._run("solve.py", ["--sat-encode", os.path.join(tmp, "P.cnf"), "--sat-c3", "pb"])
            self.assertEqual(r.returncode, 0, r.stdout[-400:] + r.stderr[-400:])
            self.assertNotEqual(hashlib.sha256(open(stale, "rb").read()).hexdigest(), before)

    def test_e3_red_base_accepted_the_stale_opb_and_wrote_null(self):
        import json
        with tempfile.TemporaryDirectory() as tmp:
            old = self._base_file(tmp, "solve.py")
            stale = os.path.join(tmp, "P.cnf.opb")
            with open(stale, "w") as fh:
                fh.write("* stale OPB from an earlier run\n")
            before = hashlib.sha256(open(stale, "rb").read()).hexdigest()
            r = self._run(old, ["--sat-encode", os.path.join(tmp, "P.cnf"), "--sat-c3", "none"])
            self.assertEqual(r.returncode, 0, r.stdout[-400:] + r.stderr[-400:])
            with open(os.path.join(tmp, "P.cnf.meta.json")) as fh:
                meta = json.load(fh)
            self.assertIsNone(meta["out_opb"], "BASE's sidecar did not say null; not the edge")
            self.assertEqual(hashlib.sha256(open(stale, "rb").read()).hexdigest(), before,
                             "BASE touched the stale OPB; not the edge")

    # E4 -- `--sat-c3 pb --sat-c5` printed no deferred-C5 warning
    def _pb_c5(self, script, tmp):
        import json
        out = os.path.join(tmp, "W.cnf")
        r = self._run(script, ["--sat-encode", out, "--sat-c3", "pb", "--sat-c5"])
        self.assertEqual(r.returncode, 0, r.stdout[-400:] + r.stderr[-400:])
        with open(out + ".meta.json") as fh:
            meta = json.load(fh)
        # precondition: this IS the edge -- a real OPB beside a deferred C5 record
        self.assertEqual(meta["out_opb"], out + ".opb")
        self.assertTrue(any(str(pb.get("status", "")).startswith("deferred")
                            for pb in meta["pb_constraints"]), meta["pb_constraints"])
        return [ln for ln in r.stdout.splitlines() if ln.startswith("[sat-encode] WARNING")]

    def test_e4_deferred_c5_beside_pb_c3_warns(self):
        with tempfile.TemporaryDirectory() as tmp:
            warn = self._pb_c5("solve.py", tmp)
            self.assertEqual(len(warn), 1, warn)
            self.assertIn("NOT emitted as clauses", warn[0])
            self.assertIn("C3 lives in the OPB companion", warn[0])

    def test_e4_red_base_printed_no_warning(self):
        with tempfile.TemporaryDirectory() as tmp:
            old = self._base_file(tmp, "solve.py")
            self.assertEqual(self._pb_c5(old, tmp), [])

    # the two sat.py changes touch argv handling and the witness loop only: emitted bytes unchanged
    def test_emitted_cnf_bytes_match_base(self):
        with tempfile.TemporaryDirectory() as tmp:
            old = self._base_file(tmp, "sat.py")
            for args in (["--emit-cnf", "plain"], ["--rigidity-cnf"]):
                a, b = os.path.join(tmp, "new.cnf"), os.path.join(tmp, "old.cnf")
                self.assertEqual(self._run("sat.py", args + [a]).returncode, 0)
                self.assertEqual(self._run(old, args + [b]).returncode, 0)
                self.assertTrue(os.path.getsize(a) > 1000, "no formula was emitted")
                self.assertEqual(hashlib.sha256(open(a, "rb").read()).hexdigest(),
                                 hashlib.sha256(open(b, "rb").read()).hexdigest(), args)
# end lane G31


class TestE31R12bFalseAcceptsPython(unittest.TestCase):
    """Lane E31 (batch 31b, 2026-10-01): Codex R12b's remaining false accepts in the Python
    instruments, each reproduced before it was fixed. Every test builds the exact fixture the
    unfixed code ACCEPTED (exit 0) and asserts the fixed code refuses it, with a positive control
    that the refusal is not a blanket one.
      #11  verify.py --fiber-sweep read each record's stored orientation and never used it; a King
           Wen record with byte 15 flipped (fails C5 as stored) exited 0.
           verify.py --check-t5-c3 printed the header version and never checked it.
      #12  verify.py --t3-membership counted duplicate walks and left them out of the verdict.
           verify.py --t3-stats passed a 16-line population (chi^2 = 0, C3 fraction 0.125).
      #16  verify.py --fiber-sweep on a NAMED artifact that does not exist exited 0.
           solve.py --extended-selftest subtest 1 checked only that three paths agreed.
    RED RUNS. verify.py has no tests.py-wide override, so this class reads ROAE_TESTS_VERIFYPY_SRC
    (a path to another verify.py) for its own subprocess and in-process runs; solve.py goes through
    _load / ROAE_TESTS_SOLVEPY_SRC as everywhere else. Against the unfixed files every test below
    fails on its refusal assertion, and every precondition still holds."""

    KW_REC = bytes.fromhex("0004080c1014181c2024282c3034383c4044484c5054585c6064686c7074787c")
    HDR1 = b"ROAE" + struct.pack("<I", 1) + struct.pack("<Q", 1) + b"\0" * 16
    CANON = "403f7202a33a9337b781f4ee17e497d5c0773c2656e16fa0db87eeccd6f3332e"

    @classmethod
    def setUpClass(cls):
        cls.vpy = os.path.abspath(os.environ.get("ROAE_TESTS_VERIFYPY_SRC", "verify.py"))
        cls.tmp = tempfile.mkdtemp(prefix="e31py_")

    @classmethod
    def tearDownClass(cls):
        shutil.rmtree(cls.tmp, ignore_errors=True)

    def _v(self, *argv, timeout=600):
        return subprocess.run([sys.executable, self.vpy] + list(argv), capture_output=True,
                              text=True, timeout=timeout, stdin=subprocess.DEVNULL)

    def _write(self, name, data, mode="wb"):
        p = os.path.join(self.tmp, name)
        with open(p, mode) as fh:
            fh.write(data)
        return p

    # ---- #11: --fiber-sweep must check the STORED orientation ----
    def test_r12b_11_fiber_sweep_refuses_a_stored_orientation_outside_the_fiber(self):
        rec = bytearray(self.KW_REC)
        self.assertEqual(rec[15], 0x3C, "precondition: byte 15 of the King Wen record")
        rec[15] = 0x3E                                  # one within-pair orientation flipped
        bad = self._write("kw_flip.bin", self.HDR1 + bytes(rec))
        good = self._write("kw.bin", self.HDR1 + self.KW_REC)
        r = self._v(bad)                                # records path: the record fails C5 as stored
        self.assertEqual(r.returncode, 1, "precondition: the flipped record must fail the records path\n" + r.stdout[-800:])
        self.assertIn("VERIFY=FAIL", r.stdout.splitlines())
        ctl = self._v(good, "--fiber-sweep")
        self.assertEqual(ctl.returncode, 0, "positive control: King Wen as stored is in its fiber\n" + ctl.stdout[-800:])
        r = self._v(bad, "--fiber-sweep")
        self.assertNotEqual(r.returncode, 0, "R12b #11: a record failing C5 as stored must not pass --fiber-sweep\n" + r.stdout[-800:])
        self.assertIn("STORED orientation outside it", r.stdout)

    def test_r12b_16_fiber_sweep_named_absent_artifact_is_an_error(self):
        missing = os.path.join(self.tmp, "no_such_artifact.bin")
        self.assertFalse(os.path.exists(missing), "precondition: the named artifact is absent")
        r = self._v(missing, "--fiber-sweep")
        self.assertEqual(r.returncode, 2, "R12b #16: a named, absent artifact is an error\n" + r.stdout[-600:])
        self.assertIn("the named artifact does not exist", r.stdout)

    # ---- #11: --check-t5-c3 must check the header version ----
    def test_r12b_11_check_t5_c3_refuses_an_unsupported_header_version(self):
        try:
            import pyarrow  # noqa: F401
        except ImportError:
            self.skipTest("pyarrow absent: --compute-stats and --check-t5-c3 need it")
        S = _load("solve")
        kw = ",".join(str(h) for h in S.binary_hexagrams)
        stream = self._write("t5_kw.out", "record\tcd=387\t%s\n" % kw, mode="w")
        raw = os.path.join(self.tmp, "t5_raw.bin")
        r = subprocess.run([sys.executable, _py_src("solve"), "--encode-solutions", raw, stream],
                           capture_output=True, text=True)
        self.assertIn("ENCODE_ROUNDTRIP=PASS", r.stdout.splitlines(), r.stdout + r.stderr)
        chunks = os.path.join(self.tmp, "t5_chunks")
        r = subprocess.run([sys.executable, _py_src("solve"), "--compute-stats", raw, chunks,
                            "--compute-stats-workers", "1"], capture_output=True, text=True)
        self.assertEqual(r.returncode, 0, r.stdout[-800:] + r.stderr[-800:])
        ctl = self._v("--check-t5-c3", raw, chunks)
        self.assertIn("T5_C3_AGREE=PASS", ctl.stdout.splitlines(), "positive control\n" + ctl.stdout[-800:])
        blob = bytearray(open(raw, "rb").read())
        blob[4:8] = struct.pack("<I", 2)
        v2 = self._write("t5_v2.bin", bytes(blob))
        self.assertEqual(open(v2, "rb").read()[4:8], struct.pack("<I", 2), "precondition: version 2 on disk")
        r = self._v("--check-t5-c3", v2, chunks)
        self.assertNotEqual(r.returncode, 0, "R12b #11: a version-2 header must not pass\n" + r.stdout[-800:])
        self.assertTrue(any(l.startswith("T5_C3_AGREE=FAIL unsupported header") for l in r.stdout.splitlines()),
                        r.stdout[-800:])

    # ---- #12: T3 population checks ----
    def _kw_draw(self, rank, cd=None):
        V = _load_path("verify_e31", self.vpy)
        walk = list(V.KW[2:])
        cd = V._t3_cd(V._t3_reconstruct(walk)) if cd is None else cd
        return "%d\tcd=%d\t%s\n" % (rank, cd, ",".join(map(str, walk)))

    def test_r12b_12_t3_membership_fails_on_a_duplicate_walk(self):
        one = self._write("t3_stream_one.out", self._kw_draw(5), mode="w")
        ctl = self._v("--t3-membership", one)
        self.assertEqual(ctl.returncode, 0, "positive control: one King Wen draw is a member\n" + ctl.stdout[-800:])
        dup = self._write("t3_stream_dup.out", self._kw_draw(5) * 2, mode="w")
        r = self._v("--t3-membership", dup)
        self.assertIn("duplicate walks                            : 1", r.stdout,
                      "precondition: the duplicate was seen\n" + r.stdout[-800:])
        self.assertEqual(r.returncode, 1, "R12b #12: a duplicate walk must fail the census\n" + r.stdout[-800:])

    def test_r12b_12_t3_stats_requires_the_preregistered_population(self):
        import contextlib, io
        V = _load_path("verify_e31_stats", self.vpy)
        N = V.T3_N
        lines = "".join(self._kw_draw((2 * i + 1) * N // 32, cd=387 if i < 2 else 400) for i in range(16))
        p = self._write("t3_stream_16.out", lines, mode="w")
        r = self._v("--t3-stats", p)
        self.assertIn("chi^2 = 0.0000", r.stdout, "precondition: the fixture is perfectly uniform\n" + r.stdout[-800:])
        self.assertIn("  (a) uniformity  : PASS", r.stdout.splitlines())
        self.assertIn("  (c) C3 fraction : within bar", r.stdout.splitlines())
        self.assertEqual(r.returncode, 1, "R12b #12: 16 draws are not the pre-registered 16 x 62,500\n" + r.stdout[-800:])
        # positive control: the same population passes when it IS the required shape
        self.assertTrue(hasattr(V, "T3_STREAMS") and hasattr(V, "T3_DRAWS_PER_STREAM"),
                        "the pre-registered shape constants are absent")
        V.T3_STREAMS, V.T3_DRAWS_PER_STREAM = 1, 16
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            rc = V.t3_stats(p)
        self.assertEqual(rc, 0, "control: the shape check must not refuse a matching population\n" + buf.getvalue()[-800:])

    # ---- #16: --extended-selftest subtest 1 must compare with the canonical sha ----
    def _ext(self, sha):
        import contextlib, io
        S = _load("solve")
        d = tempfile.mkdtemp(prefix="e31_ext_")
        self.addCleanup(shutil.rmtree, d, True)
        stub = os.path.join(d, "solve_stub")
        with open(stub, "w") as f:
            f.write("#!/bin/sh\n")
            f.write('if [ "$1" = "--branch" ]; then echo "%s  x" > "solutions_$2_$3.sha256"; '
                    'else echo "%s  solutions.bin" > solutions.sha256; fi\nexit 0\n' % ("ab" * 32, sha))
        os.chmod(stub, 0o755)
        old_tmp, tempfile.tempdir = tempfile.tempdir, d
        buf = io.StringIO()
        try:
            with contextlib.redirect_stdout(buf):
                S.extended_selftest(stub)
        finally:
            tempfile.tempdir = old_tmp
        return buf.getvalue()

    def test_r12b_16_extended_selftest_subtest_1_compares_the_canonical_sha(self):
        wrong = "cd" * 32
        out = self._ext(wrong)
        for label in ("recursive", "iterative", "iterative+v2"):
            self.assertIn("  %-14s: %s" % (label, wrong), out, "precondition: the stub ran on all three paths")
        self.assertNotIn("3-way sha mismatch", out, "precondition: the three paths agree")
        self.assertIn("  - subtest 1: the three paths agree on %s, which is NOT the canonical selftest sha" % wrong,
                      out, "R12b #16: agreement on a non-canonical sha must fail subtest 1\n" + out[-1500:])
        ctl = self._ext(self.CANON)
        self.assertIn("  recursive     : %s" % self.CANON, ctl)
        self.assertNotIn("  - subtest 1:", ctl, "positive control: the canonical sha passes subtest 1")

    # ---- Q-465 and Q-886 (3): source guards ----
    def _solve_src(self):
        with open(os.environ.get("ROAE_TESTS_SOLVE_SRC", "solve.c"), encoding="utf-8") as fh:
            return fh.read()

    def test_q465_every_printed_thread_request_carries_the_grant(self):
        src = self._solve_src()
        sites = [m.start() for m in re.finditer(r"omp_get_max_threads\(\)", src)]
        printing = []
        for pos in sites:
            pf = max(src.rfind("printf(", 0, pos), -1)
            if pf >= 0 and ";" not in src[pf:pos]:
                printing.append((pf, src.index(";", pos)))
        self.assertGreaterEqual(len(printing), 5, "precondition: the five printing request sites "
                                "(the [f1]/[f1u]/[kc-g]/[kc-t] start lines and the layer sidecar)")
        bare = [src.count("\n", 0, a) + 1 for a, b in printing
                if "omp_granted_threads()" not in src[a:b] or "granted" not in src[a:b].replace("omp_granted_threads()", "")]
        self.assertEqual(bare, [], "Q-465: these printed thread REQUESTS carry no grant beside them (lines %s)" % bare)
        helper = [l for l in src.splitlines() if l.startswith("static int omp_granted_threads(void)")]
        self.assertEqual(len(helper), 1, "the grant helper must be defined once")
        self.assertIn("omp parallel", helper[0])
        self.assertIn("omp_get_num_threads()", helper[0], "the grant is measured INSIDE a parallel region")

    def test_q886_3_selftest_children_keep_stderr(self):
        src = self._solve_src()
        child = [l for l in src.splitlines() if l.lstrip().startswith('"%s 0 > /dev/null')]
        self.assertEqual(len(child), 1, "precondition: the --selftest child command line")
        self.assertNotIn("2>&1", child[0].split("/*")[0], "Q-886 (3): the --selftest child's stderr must not be discarded")
        self.assertIn("2> selftest_child.stderr", child[0])
        auto = [l for l in src.splitlines() if '"%s --selftest > /dev/null' in l]
        self.assertEqual(len(auto), 1, "precondition: the auto-selftest command line")
        self.assertNotIn("2>&1", auto[0].split("/*")[0], "Q-886 (3): the auto-selftest must not discard --selftest's stderr")
        self.assertIn("selftest_relay_child_stderr(tempdir_template,", src)

# end class TestE31R12bFalseAcceptsPython (lane E31)


def _load_path(name, path):
    """Load a module from an explicit path (lane E31: verify.py under ROAE_TESTS_VERIFYPY_SRC)."""
    spec = importlib.util.spec_from_file_location(name, path)
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    return m


class TestE31EngineResidueWorker(unittest.TestCase):
    """Lane E31 (batch 31b, 2026-10-01), compiled legs. The binary is built from
    ROAE_TESTS_SOLVE_SRC (default solve.c), so the red run is the same class against the unfixed
    solve.c; ROAE_TESTS_VERIFYPY_SRC selects the verify.py the #16 sample leg loads.
      Q-886 (3)  the --selftest child's stderr reached /dev/null: an invalid OMP_NUM_THREADS makes
                 libgomp print a warning in BOTH processes; the parent's own copy is the
                 precondition, the child's relayed copy is the assertion, and the selftest must
                 still PASS on the canonical sha.
      Q-465      OMP_THREAD_LIMIT=1 under OMP_NUM_THREADS=2: the [f1] run: line must say granted=1
                 beside threads=2 (default: granted=2).
      R12b #14   --f1c5-verify-layer reported IDENTICAL for a v2 file whose header names another
                 layer, and for either file with stale trailing bytes.
      R12b #12   --symmetry-search --validate-counts on an empty log printed every sigma as a
                 candidate and exited 0.
      R12b #16   tests.py's only real-record fiber test skips (no solutions.bin ships); this leg
                 makes a sample with the built binary and checks every stored orientation."""

    @classmethod
    def setUpClass(cls):
        cls.tmp = tempfile.mkdtemp(prefix="e31w_")
        cls.sbin = os.path.join(cls.tmp, "solve_e31")
        src = os.environ.get("ROAE_TESTS_SOLVE_SRC", "solve.c")
        r = subprocess.run(["gcc", "-O1", "-pthread", "-fopenmp", "-o", cls.sbin, src, "-lm", "-lz"],
                           capture_output=True, text=True)
        cls.build_ok = (r.returncode == 0 and os.path.exists(cls.sbin))
        cls.build_err = "gcc rc %d: %s" % (r.returncode, r.stderr[-2000:])

    @classmethod
    def tearDownClass(cls):
        shutil.rmtree(cls.tmp, ignore_errors=True)

    def _env(self, **extra):
        env = {k: v for k, v in os.environ.items() if not k.startswith(("SOLVE_", "OMP_"))}
        env.update(extra)
        return env

    def _run(self, argv, env, timeout=600, cwd=None, stdin=subprocess.DEVNULL):
        return subprocess.run([self.sbin] + argv, cwd=cwd or self.tmp, env=env, capture_output=True,
                              text=True, timeout=timeout, stdin=stdin)

    def test_q886_3_selftest_relays_child_runtime_diagnostics(self):
        self.assertTrue(self.build_ok, self.build_err)
        r = self._run(["--selftest"], self._env(OMP_NUM_THREADS="e31-not-a-number"), timeout=1800)
        errl = r.stderr.splitlines()
        self.assertTrue(any(l.startswith("libgomp:") for l in errl),
                        "precondition: this libgomp warns about the invalid OMP_NUM_THREADS\n" + r.stderr[-1500:])
        self.assertIn("[--selftest] Actual sha256:   " + TestE31R12bFalseAcceptsPython.CANON, r.stdout.splitlines(),
                      "the selftest sha must not move\n" + r.stdout[-1500:])
        self.assertEqual(r.returncode, 0, r.stdout[-800:] + r.stderr[-800:])
        relayed = [l for l in errl if l.startswith("[--selftest child] ") and "libgomp:" in l]
        self.assertTrue(relayed, "Q-886 (3): the child's libgomp diagnostic never reached the parent's stderr\n"
                        + r.stderr[-1500:])

    def test_q465_start_line_prints_the_grant(self):
        self.assertTrue(self.build_ok, self.build_err)
        for limit, want in ((None, "granted=2"), ("1", "granted=1")):
            env = self._env(OMP_NUM_THREADS="2", SOLVE_F1_MAX_LAYER="1")
            if limit:
                env["OMP_THREAD_LIMIT"] = limit
            try:
                r = self._run(["--f1-exact-c1c2c4", "--f1-subset", "U1"], env, timeout=300)
                err = r.stderr
            except subprocess.TimeoutExpired as e:
                err = (e.stderr or b"").decode("utf-8", "replace") if isinstance(e.stderr, bytes) else (e.stderr or "")
            line = [l for l in err.splitlines() if l.startswith("[f1] run:")]
            self.assertEqual(len(line), 1, "precondition: one [f1] run: provenance line\n" + err[-1500:])
            self.assertIn("threads=2", line[0], "precondition: the request is 2")
            self.assertIn(want, line[0].split(), "Q-465: the grant must be printed beside the request: " + line[0])

    def _ladder(self, fmt):
        d = os.path.join(self.tmp, "ladder_" + fmt)
        r = self._run(["--f1-exact-c1c2c4c5", "--f1-pairs", "9", "--f1-out-of-core", d],
                      self._env(OMP_NUM_THREADS="2", SOLVE_F1_OOC_FORMAT=fmt, SOLVE_F1_KEEP_LAYERS="1"),
                      timeout=900)
        self.assertEqual(r.returncode, 0, "ladder build (%s) failed\n%s" % (fmt, r.stderr[-1500:]))
        return d

    def test_r12b_14_f1c5_verify_layer_checks_identity_and_trailing_bytes(self):
        self.assertTrue(self.build_ok, self.build_err)
        d1, d2 = self._ladder("v1"), self._ladder("v2")
        pick = None
        for k in range(9, 0, -1):
            a = os.path.join(d1, "f1c5_layer_%02d.bin" % k)
            b = os.path.join(d2, "f1c5_layer_%02d.bin" % k)
            if os.path.exists(a) and os.path.exists(b) and os.path.getsize(a) > 200:
                pick = (k, a, b)
                break
        self.assertIsNotNone(pick, "precondition: a common non-trivial layer in both ladders")
        k, v1, v2 = pick
        self.assertEqual(open(v1, "rb").read(8), b"F1C5LAY1", "precondition: v1 magic")
        self.assertEqual(open(v2, "rb").read(8), b"F1C5LAY2", "precondition: v2 magic")
        env = self._env()
        ctl = self._run(["--f1c5-verify-layer", v1, v2], env)
        self.assertEqual(ctl.returncode, 0, "positive control: the same layer in both formats\n" + ctl.stdout + ctl.stderr)
        self.assertIn("IDENTICAL", ctl.stdout)
        b2 = bytearray(open(v2, "rb").read())
        other_k = struct.unpack_from("<I", b2, 16)[0] ^ 1
        self.assertEqual(struct.unpack_from("<I", b2, 16)[0], k, "precondition: header k sits at offset 16")
        struct.pack_into("<I", b2, 16, other_k)
        wrong_k = os.path.join(self.tmp, "v2_wrong_k.bin")
        open(wrong_k, "wb").write(bytes(b2))
        tail2 = os.path.join(self.tmp, "v2_tail.bin")
        open(tail2, "wb").write(open(v2, "rb").read() + b"\0" * 7)
        tail1 = os.path.join(self.tmp, "v1_tail.bin")
        open(tail1, "wb").write(open(v1, "rb").read() + b"\0" * 32)
        for a, b, why in ((v1, wrong_k, "layer identity"), (v1, tail2, "v2 file does not end"),
                          (tail1, v2, "v1 file has trailing bytes")):
            with self.subTest(case=why):
                r = self._run(["--f1c5-verify-layer", a, b], env)
                self.assertEqual(r.returncode, 1, "R12b #14 (%s): must be a mismatch\n%s%s" % (why, r.stdout, r.stderr))
                self.assertIn(why, r.stderr)

    def test_r12b_12_symmetry_search_empty_log_is_an_error(self):
        self.assertTrue(self.build_ok, self.build_err)
        r = self._run(["--symmetry-search", "--validate-counts"], self._env(OMP_NUM_THREADS="2"), timeout=300)
        self.assertIn("Non-trivial on (pair,orient) space:     47", r.stdout, "precondition: phases 1 and 2 ran")
        self.assertIn("parsed 0 sub-branch yields from stdin", r.stderr, "precondition: the log was empty")
        self.assertNotIn("**CANDIDATE SYMMETRY**", r.stdout, "R12b #12: nothing was compared")
        self.assertIn("SYMMETRY_PHASE3=NO_INPUT", r.stderr.splitlines())
        self.assertEqual(r.returncode, 1)
        log = os.path.join(self.tmp, "one_yield.log")
        with open(log, "w") as fh:
            fh.write("Wrote 7 solutions to sub_1_0_2_0_3_0.bin\n")
        with open(log) as fh:
            ctl = self._run(["--symmetry-search", "--validate-counts"], self._env(OMP_NUM_THREADS="2"),
                            timeout=300, stdin=fh)
        self.assertEqual(ctl.returncode, 0, "control: a non-empty log still exits 0\n" + ctl.stderr[-800:])
        self.assertIn("parsed 1 sub-branch yields from stdin", ctl.stderr)

    def test_r12b_16_real_sample_stored_orientations_are_in_their_fibers(self):
        self.assertTrue(self.build_ok, self.build_err)
        d = tempfile.mkdtemp(dir=self.tmp)
        env = self._env(SOLVE_THREADS="2", SOLVE_NODE_LIMIT="10000000", SOLVE_HASH_LOG2="16",
                        SOLVE_ALLOW_SUB_CANONICAL="1", SOLVE_SKIP_CANONICAL_LOCK="1",
                        SOLVE_SKIP_AUTO_SELFTEST="1", SOLVE_SKIP_DISK_CHECK="1",
                        SOLVE_SKIP_BINARY_SNAPSHOT="1", SOLVE_SKIP_AUTO_MANIFEST="1",
                        SOLVE_SKIP_IOPS_CHECK="1")
        r = self._run(["0"], env, timeout=900, cwd=d)
        path = os.path.join(d, "solutions.bin")
        self.assertEqual(r.returncode, 0, r.stderr[-1500:])
        self.assertTrue(os.path.exists(path), "precondition: the run wrote solutions.bin")
        V = _load_path("verify_e31_fiber", os.path.abspath(os.environ.get("ROAE_TESTS_VERIFYPY_SRC", "verify.py")))
        seen = 0
        for i, perm, orient in V._fiber_records(path, limit=400):
            self.assertEqual(orient[0], 0, "record %d: slot 0 must carry the C4 orientation" % i)
            self.assertEqual(V.fiber_count(perm, 63, fixed={s: orient[s] for s in range(1, 32)}), 1,
                             "record %d: its stored orientation is not in its fiber" % i)
            seen += 1
        self.assertGreater(seen, 1, "precondition: the sample holds real records, not only King Wen")

# end class TestE31EngineResidueWorker (lane E31)


class TestB31MergeCompleteness(unittest.TestCase):
    """Lane B31 (batch 31c): Q-888 (1), (2), (3), (5) and Q-317 (2), the merge-completeness residue that
    CX-235 part 7 and CX-239 part 9 listed as not fixed.

    (1) A SIGTERM-stopped --branch wrote its partial set to solutions_<p>_<o>.bin and its .sha256 and
        exited 0; it now writes solutions_<p>_<o>.partial.bin/.partial.sha256, prints BRANCH_OUTPUT=PARTIAL
        and exits 36. (2) The parallel --sub-branch path wrote no enum_incomplete.txt; it now does, until
        it finishes. (3) A deleted shard that no checkpoint line claims merged with exit 0; the merge gate
        now reads shard_manifest.txt and refuses an absent listed shard (MERGE_SHARD=MISSING, exit 20).
        (5) promote_orphaned_shards() read only a gz shard's size trailer; a gz orphan whose CRC-32 or size
        trailer is wrong is now refused and its cell walked again. Q-317 (2): a task stopped by
        SOLVE_PER_TASK_NODE_LIMIT was reported completed=1 and the sub-branch EXHAUSTED; it is now
        completed=0 and the sub-branch BUDGETED.

    Every fixture is a real run of a -O1 -fopenmp build of ROAE_TESTS_SOLVE_SRC (default solve.c). A
    SIGTERM is sent only once /proc/<pid>/status shows the handler installed, and every stopped case
    asserts the handler's line first. Each refusal test asserts its precondition before its verdict.
    """
    ROOT = os.path.dirname(os.path.abspath(__file__))
    MARKER = "enum_incomplete.txt"
    SIG_LINE = "*** Signal received"
    SMALL = {"SOLVE_HASH_LOG2": "16", "SOLVE_DEPTH": "2", "SOLVE_THREADS": "4"}
    SUB = ["--sub-branch", "1", "0", "2", "0", "3", "0", "0", "4"]
    STOPPER = r"""#!/bin/bash
"$@" & p=$!
for i in $(seq 600); do
  m=$(awk '/^SigCgt/{print $2}' /proc/$p/status 2>/dev/null)
  [ -n "$m" ] && [ $(( 0x$m & 0x4000 )) -ne 0 ] && break
  sleep 0.1
done
sleep "${B31_STOP_AFTER:-1.0}"; kill -TERM $p; wait $p
"""
    CELL_RE = re.compile(r"pair1 (\d+) orient1 (\d+) pair2 (\d+) orient2 (\d+)\): .*?, (\d+) solutions,")

    @classmethod
    def setUpClass(cls):
        cls.tmp = tempfile.mkdtemp(prefix="b31_")
        cls.stopper = os.path.join(cls.tmp, "stopper.sh")
        with open(cls.stopper, "w") as fh:
            fh.write(cls.STOPPER)
        os.chmod(cls.stopper, 0o755)
        cls.sbin = os.path.join(cls.tmp, "solve_b31")
        src = os.environ.get("ROAE_TESTS_SOLVE_SRC", "solve.c")
        r = subprocess.run(["gcc", "-O1", "-pthread", "-fopenmp", "-o", cls.sbin, src, "-lm", "-lz"],
                           cwd=cls.ROOT, capture_output=True, text=True)
        cls.build_ok = r.returncode == 0 and os.path.exists(cls.sbin)
        cls.build_err = "gcc rc %d: %s" % (r.returncode, r.stderr[-2000:])
        if not cls.build_ok:
            return
        skip = {"SOLVE_SKIP_AUTOMERGE": "1", "SOLVE_PER_SUB_BRANCH_LIMIT": "20000"}
        cls.fin = cls._run("fin", ["0", "4"], skip)
        cls.branch_fin = cls._run("branch_fin", ["--branch", "1", "0", "0", "2"], {"SOLVE_PER_SUB_BRANCH_LIMIT": "2000"})
        cls.branch_stop = cls._run("branch_stop", ["--branch", "1", "0", "0", "2"],
                                   {"SOLVE_PER_SUB_BRANCH_LIMIT": "200000000"}, stop=True)
        cls.sub_stop = cls._run("sub_stop", cls.SUB, {"SOLVE_ALLOW_SUB_CANONICAL": "1",
                                                      "SOLVE_PER_TASK_NODE_LIMIT": "100000000",
                                                      "SOLVE_NODE_LIMIT": "100000000000"}, stop=True)
        cls.sub_cap = cls._run("sub_cap", cls.SUB, {"SOLVE_ALLOW_SUB_CANONICAL": "1",
                                                    "SOLVE_PER_TASK_NODE_LIMIT": "1000"})

    @classmethod
    def tearDownClass(cls):
        if getattr(cls, "tmp", None) and os.path.isdir(cls.tmp):
            shutil.rmtree(cls.tmp, ignore_errors=True)

    @classmethod
    def _env(cls, extra):
        env = {k: v for k, v in os.environ.items() if not k.startswith("SOLVE_")}
        env.update(cls.SMALL)
        env.update(extra)
        return env

    @classmethod
    def _run(cls, name, argv, extra, stop=False, d=None):
        if d is None:
            d = os.path.join(cls.tmp, name)
            os.makedirs(d)
        cmd = ([cls.stopper] if stop else []) + [cls.sbin] + argv
        p = subprocess.run(cmd, cwd=d, env=cls._env(extra), text=True, timeout=900,
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        return {"rc": p.returncode, "out": p.stdout, "err": p.stderr, "dir": d, "argv": argv, "extra": extra}

    def setUp(self):
        if not self.build_ok:
            self.fail("solve.c did not build, so nothing was verified: " + self.build_err)

    def _copy(self, run, name):
        d = tempfile.mkdtemp(prefix=name + "_", dir=self.tmp)
        shutil.rmtree(d)
        shutil.copytree(run["dir"], d, symlinks=True)
        return d

    def _merge(self, d):
        p = subprocess.run([self.sbin, "--merge"], cwd=d, env=self._env({}), text=True, timeout=900,
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        return p.returncode, p.stdout, p.stderr

    def _ckpt_files(self, d):
        return sorted(f for f in os.listdir(d) if re.fullmatch(r"checkpoint(_t\d+)?\.txt", f))

    def _ckpt_text(self, d):
        out = ""
        for f in self._ckpt_files(d):
            with open(os.path.join(d, f)) as fh:
                out += fh.read()
        return out

    def _drop_cell_lines(self, d, cell):
        """Remove every checkpoint line naming cell ('pair1 P orient1 O pair2 P2 orient2 O2)')."""
        for f in self._ckpt_files(d):
            p = os.path.join(d, f)
            with open(p) as fh:
                keep = [l for l in fh if cell not in l]
            with open(p, "w") as fh:
                fh.writelines(keep)
        self.assertNotIn(cell, self._ckpt_text(d), "precondition: a checkpoint line still names the cell")

    def _gz_victim(self, d):
        """A gz shard that holds >= 1 record and is listed in shard_manifest.txt: (shard, cell, records)."""
        with open(os.path.join(d, "shard_manifest.txt")) as fh:
            listed = {l.split("\t")[0] for l in fh if "\t" in l}
        for m in self.CELL_RE.finditer(self._ckpt_text(d)):
            p1, o1, p2, o2, n = m.groups()
            shard = "sub_%s_%s_%s_%s.bin" % (p1, o1, p2, o2)
            path = os.path.join(d, shard)
            if int(n) > 0 and shard in listed and os.path.exists(path):
                with open(path, "rb") as fh:
                    raw = fh.read()
                if raw[:2] == b"\x1f\x8b" and len(gzip.decompress(raw)) == 32 * int(n):
                    return shard, "pair1 %s orient1 %s pair2 %s orient2 %s)" % (p1, o1, p2, o2), int(n)
        self.fail("precondition: no gz shard with records is listed in shard_manifest.txt")

    # ------------------------------------------------------------------ Q-888 (1)
    def test_q888_1_a_stopped_branch_writes_only_the_partial_names_and_exits_36(self):
        run = self.branch_stop
        self.assertIn(self.SIG_LINE, run["err"], "precondition: the SIGTERM did not reach the handler")
        self.assertIn("ENUM_RUN=STOPPED", run["out"].splitlines(), run["out"][-800:])
        self.assertIn("Sub-branch INTERRUPTED", self._ckpt_text(run["dir"]),
                      "precondition: the kill landed before every cell was finished (no INTERRUPTED line)")
        d = run["dir"]
        self.assertFalse(os.path.exists(os.path.join(d, "solutions_1_0.bin")),
                         "a stopped --branch wrote its partial set under the name a finished run writes")
        self.assertFalse(os.path.exists(os.path.join(d, "solutions_1_0.sha256")))
        self.assertEqual(run["rc"], 36, (run["out"] + run["err"])[-1500:])
        self.assertIn("BRANCH_OUTPUT=PARTIAL", run["out"].splitlines())
        self.assertIn("Q-888 (1)", run["err"])
        for f in ("solutions_1_0.partial.bin", "solutions_1_0.partial.sha256"):
            self.assertTrue(os.path.exists(os.path.join(d, f)), f)
        with open(os.path.join(d, "solutions_1_0.partial.sha256")) as fh:
            self.assertEqual(len(fh.readline().split()[0]), 64)

    def test_q888_1_a_finished_branch_is_unchanged(self):
        run = self.branch_fin
        self.assertEqual(run["rc"], 0, run["err"][-1500:])
        self.assertIn("ENUM_RUN=FINISHED", run["out"].splitlines())
        self.assertNotIn("BRANCH_OUTPUT=PARTIAL", run["out"].splitlines())
        for f in ("solutions_1_0.bin", "solutions_1_0.sha256"):
            self.assertTrue(os.path.exists(os.path.join(run["dir"], f)), f)
        self.assertFalse(any(".partial." in f for f in os.listdir(run["dir"])))

    # ------------------------------------------------------------------ Q-888 (2)
    def test_q888_2_a_stopped_parallel_sub_branch_keeps_the_marker(self):
        run = self.sub_stop
        self.assertIn(self.SIG_LINE, run["err"], "precondition: the SIGTERM did not reach the handler")
        self.assertIn("*** Parallel --sub-branch INTERRUPTED: ", run["err"], "precondition: the parallel path ran and was stopped")
        self.assertTrue(os.path.exists(os.path.join(run["dir"], self.MARKER)),
                        "a stopped parallel --sub-branch left no run-in-progress marker")
        rc, out, err = self._merge(self._copy(run, "sub_stop_merge"))
        self.assertEqual(rc, 35, (out + err)[-1500:])
        self.assertIn("MERGE_INPUT=INCOMPLETE", err.splitlines())

    def test_q888_2_a_finished_parallel_sub_branch_removes_the_marker(self):
        run = self.sub_cap
        self.assertEqual(run["rc"], 0, run["err"][-1500:])
        self.assertIn("ENUM_RUN=FINISHED", run["out"].splitlines())
        self.assertFalse(os.path.exists(os.path.join(run["dir"], self.MARKER)))

    # ------------------------------------------------------------------ Q-888 (3)
    def test_q888_3_an_unclaimed_shard_listed_in_the_manifest_is_missed_by_name(self):
        self.assertEqual(self.fin["rc"], 0, self.fin["err"][-1500:])
        d = self._copy(self.fin, "unclaimed")
        shard, cell, n = self._gz_victim(d)
        self.assertGreaterEqual(n, 1, "precondition: the shard held a record")
        self._drop_cell_lines(d, cell)
        os.remove(os.path.join(d, shard))
        rc, out, err = self._merge(d)
        self.assertEqual(rc, 20, "a deleted shard no checkpoint line claims was merged without it: " + (out + err)[-1500:])
        self.assertIn("MERGE_SHARD=MISSING", err.splitlines())
        self.assertIn(shard, err)
        self.assertIn("shard_manifest.txt lists it", err)
        self.assertFalse(os.path.exists(os.path.join(d, "solutions.bin")))

    def test_q888_3_a_finished_directory_still_merges_and_says_what_it_checked(self):
        d = self._copy(self.fin, "manifest_ok")
        rc, out, err = self._merge(d)
        self.assertEqual(rc, 0, (out + err)[-1500:])
        self.assertIn("Shard manifest cross-ref: all", out)
        d = self._copy(self.fin, "manifest_none")
        os.remove(os.path.join(d, "shard_manifest.txt"))
        rc, out, err = self._merge(d)
        self.assertEqual(rc, 0, (out + err)[-1500:])
        self.assertIn("that check is SKIPPED, not passed (Q-888 (3))", err)

    # ------------------------------------------------------------------ Q-888 (5)
    def test_q888_5_a_gz_orphan_with_a_bad_trailer_is_not_promoted(self):
        self.assertEqual(self.fin["rc"], 0, self.fin["err"][-1500:])
        d = self._copy(self.fin, "trailer")
        shard, cell, n = self._gz_victim(d)
        path = os.path.join(d, shard)
        with open(path + ".budget") as fh:
            self.assertEqual(fh.read().split()[0], "20000", "precondition: the orphan's budget sidecar matches the relaunch")
        with open(path, "rb") as fh:
            raw = bytearray(fh.read())
        crc, isize = struct.unpack("<II", bytes(raw[-8:]))
        raw[-8:] = struct.pack("<II", crc ^ 0xFFFFFFFF, isize + 32)
        with open(path, "wb") as fh:
            fh.write(bytes(raw))
        self.assertEqual((isize + 32) % 32, 0, "precondition: the damaged size trailer passes the size check")
        with self.assertRaises(Exception, msg="precondition: the damaged shard must fail a gzip check"):
            gzip.decompress(bytes(raw))
        self._drop_cell_lines(d, cell)          # an orphan: the line was lost with the batch window
        os.remove(os.path.join(d, "shard_manifest.txt"))   # written after the last manifest snapshot
        r = self._run("", self.fin["argv"], self.fin["extra"], d=d)
        self.assertEqual(r["rc"], 0, r["err"][-1500:])
        self.assertNotIn("promoted=1,", r["err"], "the damaged orphan was promoted: " + r["err"][-1500:])
        self.assertIn("Q-888 (5)", r["err"])
        self.assertIn(shard, r["err"])
        with open(path, "rb") as fh:
            self.assertEqual(len(gzip.decompress(fh.read())), 32 * n, "the refused cell was not walked again")

    # ------------------------------------------------------------------ Q-317 (2)
    def test_q317_2_a_capped_task_is_not_completed_and_the_sub_branch_is_budgeted(self):
        run = self.sub_cap
        self.assertEqual(run["rc"], 0, run["err"][-1500:])
        self.assertNotIn(self.SIG_LINE, run["err"])
        self.assertNotIn("[BUDGET]", run["err"], "precondition: no node budget fired, only the per-task cap")
        import csv
        with open(os.path.join(run["dir"], "per_task_stats.csv")) as fh:
            rows = list(csv.DictReader(fh))
        # Which tasks were certainly capped (fix 2026-10-02, CX-251 note): backtrack() counts the node
        # at entry and checks SOLVE_PER_TASK_NODE_LIMIT only at its 65536-node flush point, and every
        # task ends with a residual flush, so a task's first check comes at its own 65536th node. A
        # task that reached 65536 nodes therefore had the cap (1000) fire there, and a capped task
        # stops at 65536 plus a few unwinding entries (measured: 66037..66138 on this fixture, every
        # one of its 2488 tasks). The old "> 65536 + 1000" bound sat above every capped count and
        # could never be met. The workload is node-driven (no wall-time limit, SOLVE_THREADS=4), so
        # the set of capped tasks does not depend on machine speed or core count.
        capped = [r for r in rows if int(r["nodes"]) >= 65536]
        self.assertGreater(len(capped), 0, "precondition: no task walked far enough to be certainly capped")
        self.assertEqual([r["task_idx"] for r in capped if r["completed"] == "1"], [],
                         "a task stopped by SOLVE_PER_TASK_NODE_LIMIT was reported completed=1")
        self.assertIn("*** Parallel --sub-branch BUDGETED: ", run["err"])
        self.assertNotIn("*** Parallel --sub-branch EXHAUSTED: ", run["err"])
        self.assertIn("Sub-branch BUDGETED (parallel", self._ckpt_text(run["dir"]))
        self.assertNotIn("Sub-branch EXHAUSTED (parallel", self._ckpt_text(run["dir"]))

    def test_q317_2_the_old_predicate_is_gone(self):
        with open(os.path.join(self.ROOT, os.environ.get("ROAE_TESTS_SOLVE_SRC", "solve.c"))) as fh:
            src = fh.read()
        self.assertIn("int task_completed_cleanly = (", src, "precondition: the predicate is still there to check")
        self.assertNotIn("int task_completed_cleanly = (!sub_sub_budget_hit && !global_timed_out);", src)

# end class TestB31MergeCompleteness (lane B31)



class TestC31KcQuerySurface(unittest.TestCase):
    """Batch 31c (lane C31): the KC query-surface residue of Q-320 (Codex N04/A04/R10), Q-326
    (Codex Z03) and Q-533 (the G2 disposition's section 7). Each code row has a case that the
    unfixed tree fails and the fixed tree passes, and each asserts that its probe really is the
    defect case before it reads the verdict.
      Q-320 (6)  --kc-enum-desc's #provenance line names limit= and c3max=.
      Q-320 (3)  --kc-scan prints KC_SCAN=FAIL on a ladder-open failure; atlas_load refuses a gate
                 status outside the producer's four values (and the FAILED / not-run states).
      Q-320 (5)  tr12_repro.sh's run header records the binary's sha256 and the git identity.
      Q-326 (2)  the out-of-core reader refuses an n=31 manifest that is not the production tuple.
      Q-326 (6)  --kc-scan, --kc-scan-merge and --kc-profile bind start, pair-table hash and budget.
      Q-533      a failed --kc-scan no longer leaves the previous OUT standing.
    Regression cover for three KCQ fixes that landed earlier without a checked-in test (KCQ03 #2,
    KCQ03 #3, KCQ04 #4) rides along; those cases are green on the base by construction.
    ROAE_TESTS_SOLVE_SRC swaps the C source under test (mutants)."""

    ROOT = os.path.dirname(os.path.abspath(__file__))
    ATLAS31 = os.path.join("runs", "20260906_kc_ladders_n31", "atlas_n31.json")
    WALK_RE = re.compile(r"^[0-9]+(,[0-9]+)+$")

    @classmethod
    def setUpClass(cls):
        cls.tmp = tempfile.mkdtemp(prefix="c31_")
        cls.sbin = os.path.join(cls.tmp, "solve_c31")
        cls.fdir, cls.gdir = os.path.join(cls.tmp, "f"), os.path.join(cls.tmp, "g")
        cls.err = ""
        src = os.environ.get("ROAE_TESTS_SOLVE_SRC", os.path.join(cls.ROOT, "solve.c"))
        r = subprocess.run(["gcc", "-O1", "-pthread", "-fopenmp", "-o", cls.sbin, src, "-lm", "-lz"],
                           capture_output=True, text=True)
        cls.ok = r.returncode == 0 and os.path.exists(cls.sbin)
        cls.err += r.stderr[-1500:]
        if cls.ok:
            for argv in ([cls.sbin, "--kc-build", cls.fdir, "--f1-pairs", "9"],
                         [cls.sbin, "--kc-g-build", cls.gdir, "--f1-pairs", "9"]):
                r = subprocess.run(argv, capture_output=True, text=True, timeout=600)
                if r.returncode != 0:
                    cls.ok = False
                    cls.err += "%s rc %d\n%s" % (argv[1], r.returncode, (r.stdout + r.stderr)[-1500:])
                    break

    @classmethod
    def tearDownClass(cls):
        shutil.rmtree(cls.tmp, ignore_errors=True)

    # ---- helpers ---------------------------------------------------------------------------
    def _need(self):
        self.assertTrue(self.ok, self.err)

    def _run(self, *args, env=None, timeout=600):
        e = dict(os.environ)
        for k in ("SOLVE_KC_SCAN_START_BLOCK", "SOLVE_KC_SCAN_STOP_AFTER_BLOCKS", "SOLVE_KC_SCAN_TABLES"):
            e.pop(k, None)
        e.update(env or {})
        r = subprocess.run([self.sbin] + list(args), capture_output=True, text=True, env=e,
                           timeout=timeout, cwd=self.tmp)
        return r.returncode, r.stdout.splitlines(), r.stdout + r.stderr

    @staticmethod
    def _pl_hash(n, start_exit, pl):
        """solve.c f1_pl_hash, re-derived here (FNV-1a over n, start exit and the pair list)."""
        h = 0xcbf29ce484222325
        for v in [n, start_exit] + list(pl):
            h ^= v & 0xFFFFFFFFFFFFFFFF
            h = (h * 0x100000001b3) & 0xFFFFFFFFFFFFFFFF
        return h

    @staticmethod
    def _manifest(path):
        out = {}
        with open(path) as fh:
            for line in fh.read().splitlines()[1:]:
                if "=" in line:
                    k, v = line.split("=", 1)
                    out[k] = v
        return out

    def _first_walk(self):
        rc, lines, out = self._run("--kc-enum", self.fdir, "--kc-limit", "1")
        walks = [l for l in lines if self.WALK_RE.match(l)]
        self.assertEqual((rc, len(walks)), (0, 1), out)
        return walks[0]

    def _g_with_swapped_pairs(self):
        """A copy of the n=9 g ladder whose pair list has its first two entries swapped, with the
        manifest's and every layer header's pl_hash re-derived to match. n, total, start exit and
        budget are unchanged, so only a binding that covers the pair table can tell."""
        d = os.path.join(self.tmp, "g_swapped")
        if os.path.isdir(d):
            return d
        shutil.copytree(self.gdir, d)
        mpath = os.path.join(d, "g_manifest.txt")
        with open(mpath) as fh:
            text = fh.read()
        m = self._manifest(mpath)
        n, se = int(m["n"]), int(m["start_exit"])
        pl = [int(x) for x in m["pl"].split(",")]
        self.assertEqual(len(pl), n, "precondition: the manifest lists n pairs")
        self.assertEqual("%016x" % self._pl_hash(n, se, pl), m["pl_hash"],
                         "precondition: this re-derivation of f1_pl_hash agrees with the engine")
        sw = [pl[1], pl[0]] + pl[2:]
        self.assertNotEqual(sw, pl, "precondition: the swap changes the pair list")
        newh = self._pl_hash(n, se, sw)
        text = text.replace("pl=" + m["pl"] + "\n", "pl=" + ",".join(map(str, sw)) + "\n", 1)
        text = text.replace("pl_hash=" + m["pl_hash"] + "\n", "pl_hash=%016x\n" % newh, 1)
        with open(mpath, "w") as fh:
            fh.write(text)
        for k in range(n + 1):
            lp = os.path.join(d, "g_layer_%02d.bin" % k)
            with open(lp, "r+b") as fh:
                fh.seek(24)
                fh.write(struct.pack("<Q", newh))
        return d

    def _n31_manifest_dir(self, name, start_exit=0, pl=None, b0=(2, 8, 13, 7, 1)):
        pl = list(range(1, 32)) if pl is None else pl
        d = os.path.join(self.tmp, name)
        os.makedirs(d, exist_ok=True)
        with open(os.path.join(d, "f1c5_manifest.txt"), "w") as fh:
            fh.write("f1c5_manifest_v1\nn=31\nstart_exit=%d\npl=%s\npl_hash=%016x\nb0=%s\n"
                     "last_complete_k=31\n" % (start_exit, ",".join(map(str, pl)),
                                               self._pl_hash(31, start_exit, pl),
                                               ",".join(map(str, b0))))
        return d

    # ================================================================== Q-320 (6)
    def test_q320_6_enum_desc_provenance_names_limit_and_c3max(self):
        self._need()
        rc, lines, out = self._run("--kc-enum-desc", self.fdir, "--kc-limit", "3", "--kc-c3-max", "387")
        self.assertEqual(rc, 0, out)
        self.assertEqual(len([l for l in lines if self.WALK_RE.match(l)]), 3,
                         "precondition: --kc-limit 3 emitted a 3-walk PREFIX\n" + out)
        prov = [l for l in lines if l.startswith("#provenance\tengine=solve.c/kc-enum-desc\t")]
        self.assertEqual(len(prov), 1, out)
        fields = prov[0].split("\t")
