        self.assertIn("TRANSCRIPTS_GATE=PASS", out.splitlines(), out[-1500:])
        rc, out = self._run({"reports/X.md": self.BLOCK}, self._row(cls="rerun", ev="TestQ29TranscriptRegistry"))
        self.assertIn("TRANSCRIPTS_GATE=PASS", out.splitlines(), out[-1500:])
